public class AVR8_6_GCC_O3_EmulatorTest : ProcessorEmulatorTestAdapter {

	private static readonly string LANGUAGE_ID = "avr8:LE:16:atmega256";
	private static readonly string COMPILER_SPEC_ID = "gcc";

	private static readonly string[] REG_DUMP_SET = new string[] {};

	public AVR8_6_GCC_O3_EmulatorTest(string name)
    : base(name, LANGUAGE_ID, COMPILER_SPEC_ID, REG_DUMP_SET)
    {
	}

	/* @Override */
	protected string getProcessorDesignator() {
		return "AVR8_6_GCC_O3";
	}

	/* @Override */
	protected void initializeState(EmulatorTestRunner testRunner, Program program)
    {
		base.initializeState(testRunner, program);
		// These eliminate "uninitialized register" errors. Not strictly needed, but helps find actual problems.
		testRunner.setRegister("SP", 0x0);
		testRunner.setRegister("R1", 0x0);
		testRunner.setRegister("Y", 0x0);
		testRunner.setRegister("R25R24", 0x0);
	}

	/* @Override */
	protected void setAnalysisOptions(Options analysisOptions) {
		base.setAnalysisOptions(analysisOptions);
		analysisOptions.setBoolean("Reference", false); // too many bad disassemblies
		analysisOptions.setBoolean("Data Reference", false);
	}

